import test from 'node:test';
import assert from 'node:assert/strict';
import {analyzeMarkdown,renderMarkdown,extractMentions,safeMarkdownUrl} from '../src/markdown.js';
const tick=String.fromCharCode(96);
function agrees(source,expected){const result=analyzeMarkdown(source);assert.deepEqual(result.mentions,expected);assert.equal(renderMarkdown(source),result.html);assert.deepEqual(extractMentions(source),expected);return result.html;}
test('variable backtick spans contain shorter and longer runs without semantic mentions',()=>{
  const source=tick.repeat(2)+'@hidden '+tick+'literal'+tick+' '+tick.repeat(3)+' @alsoHidden'+tick.repeat(2)+' @visible';
  const html=agrees(source,['visible']);assert.ok(html.includes('<code>@hidden'));assert.equal((html.match(/class="mention"/g)??[]).length,1);
});
test('code spans normalize multiline content and trim one surrounding space pair',()=>{
  const html=agrees('Before '+tick.repeat(2)+' @hidden\n**literal** '+tick.repeat(2)+' after @visible',['visible']);
  assert.ok(html.includes('<code>@hidden **literal**</code>'));assert.ok(!html.includes('<strong>'));
});
test('escaped delimiters stay literal while escapes inside code remain code text',()=>{
  const source='\\'+tick+' @visible '+tick.repeat(2)+'\\'+tick+' @hidden'+tick.repeat(2)+' \\@escaped';
  const html=agrees(source,['visible']);assert.ok(html.includes('<code>\\'+tick+' @hidden</code>'));
});
test('wide backtick fences require their own character and a closing run at least as long',()=>{
  const source=tick.repeat(4)+'js extra information\n@hidden\n'+tick.repeat(3)+'\n~~~\n@alsoHidden\n'+tick.repeat(5)+'\n@visible';
  const html=agrees(source,['visible']);assert.ok(html.includes('class="language-js"'));assert.ok(html.includes(tick.repeat(3)+'\n~~~\n@alsoHidden'));
});
test('tilde fences permit info text while keeping code HTML and mentions inert',()=>{
  const html=agrees('~~~~ <bad onclick="x">\n<script> @hidden\n~~~~\n@visible',['visible']);
  assert.ok(html.includes('&lt;script&gt; @hidden'));assert.ok(!html.includes('<script>'));assert.ok(!html.includes('class="language-'));
});
test('unclosed variable fences consume the remaining container safely',()=>{
  for(const marker of [tick.repeat(5),'~~~~']){
    const html=agrees(marker+'\n@hidden <img src=x>\n'+marker.slice(1),[]);assert.ok(html.includes('&lt;img src=x&gt;'));
  }
});
test('indented code accepts tabs blank lines and literal mention references',()=>{
  const html=agrees('    @hidden\n\n\t@[Hidden](user:hidden)\n\n@visible',['visible']);
  assert.ok(html.includes('<pre><code>@hidden\n\n@[Hidden](user:hidden)</code></pre>'));
});
test('indentation cannot start a code block in the middle of an existing paragraph',()=>{
  const html=agrees('Paragraph\n    @visible\n\n    @hidden',['visible']);
  assert.ok(html.includes('<p>Paragraph<br>'));assert.ok(html.includes('<pre><code>@hidden'));
});
test('nested list continuations and indented code use the containing item indentation',()=>{
  const source='- outer @outer\n  - child\n\n        @hidden\n\n    continuation @inside\n\noutside @outside';
  const html=agrees(source,['outer','inside','outside']);assert.equal((html.match(/<ul>/g)??[]).length,2);assert.ok(html.includes('<pre><code>@hidden</code></pre>'));
});
test('nested quote list and continuation code share the same block parser',()=>{
  const source='> - item\n>\n>       @hidden\n>\n>   continuation @visible\n\noutside @outside';
  const html=agrees(source,['visible','outside']);assert.ok(html.includes('<blockquote><ul>'));assert.ok(html.includes('<pre><code>@hidden</code></pre>'));
});
test('quoted fenced code ends at the quote boundary and cannot swallow outside mentions',()=>{
  const source='> '+tick.repeat(4)+'\n> @hidden\noutside @visible';
  const html=agrees(source,['visible']);assert.ok(html.includes('<blockquote><pre><code>@hidden</code></pre></blockquote>'));
});
test('list-contained fences keep blockquote and list markers literal in code',()=>{
  const source='1. task\n   ~~~~ text\n   > @hidden\n   - @alsoHidden\n   ~~~~\n2. @visible';
  const html=agrees(source,['visible']);assert.ok(html.includes('&gt; @hidden\n- @alsoHidden'));assert.ok(html.includes('<ol>'));
});
test('balanced link labels and destinations render formatting and literal code consistently',()=>{
  const source='[**Read** [nested] '+tick+'@hidden'+tick+'](https://example.test/a_(b)) @visible';
  const html=agrees(source,['visible']);assert.ok(html.includes('href="https://example.test/a_(b)"'));assert.ok(html.includes('<strong>Read</strong> [nested] <code>@hidden</code>'));
});
test('escaped URL parentheses and emphasis delimiters cannot break safe inline structure',()=>{
  const html=agrees('[Read](https://example.test/a\\(b\\)) **bold \\** text** @visible',['visible']);
  assert.ok(html.includes('href="https://example.test/a(b)"'));assert.ok(html.includes('<strong>bold ** text</strong>'));
});
test('malformed and unsafe links remain escaped literal input without active attributes',()=>{
  for(const source of ['[<img src=x>](javascript:alert(1))','[bad](data:text/html,<svg>)','[broken](https://example.test/a']){
    const html=renderMarkdown(source);assert.ok(!html.includes('<a '));assert.ok(!html.includes('<img'));assert.ok(!html.includes('<svg>'));
  }
  assert.equal(safeMarkdownUrl('javascript:alert(1)'),null);
});
test('deep containers and malformed brackets remain bounded deterministic escaped input',()=>{
  const source='> '.repeat(80)+'<script> @hidden';const first=analyzeMarkdown(source);assert.deepEqual(first.mentions,[]);assert.equal(renderMarkdown(source),first.html);assert.deepEqual(extractMentions(source),[]);assert.equal(analyzeMarkdown(source).html,first.html);assert.ok(!first.html.includes('<script>'));
  assert.deepEqual(extractMentions('> '.repeat(31)+'@visible'),['visible']);assert.deepEqual(extractMentions('> '.repeat(32)+'@literal'),[]);
  const malformed='['.repeat(10000)+'literal';assert.equal(renderMarkdown(malformed),'<p>'+malformed+'</p>');
});
